import javax.crypto.Cipher;
import javax.crypto.Mac;
import javax.crypto.SecretKey;
import javax.crypto.spec.GCMParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.util.Map;
import java.util.stream.Collectors;

public class CryptoExamples {

    // 1) AES-256-GCM 字段加密：每条记录独立随机 IV
    public static byte[] encryptField(byte[] plaintext, SecretKey key) throws Exception {
        byte[] iv = new byte[12]; // GCM 推荐 12 字节 nonce
        SecureRandom.getInstanceStrong().nextBytes(iv);
        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        cipher.init(Cipher.ENCRYPT_MODE, key, new GCMParameterSpec(128, iv));
        byte[] ciphertext = cipher.doFinal(plaintext); // 末尾 16B 是 auth tag
        return ByteBuffer.allocate(iv.length + ciphertext.length)
                .put(iv).put(ciphertext).array();
    }

    public static byte[] decryptField(byte[] blob, SecretKey key) throws Exception {
        ByteBuffer buf = ByteBuffer.wrap(blob);
        byte[] iv = new byte[12];
        buf.get(iv);
        byte[] ciphertext = new byte[buf.remaining()];
        buf.get(ciphertext);
        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        cipher.init(Cipher.DECRYPT_MODE, key, new GCMParameterSpec(128, iv));
        return cipher.doFinal(ciphertext); // 认证失败会抛 AEADBadTagException
    }

    // 2) HMAC-SHA256 接口签名：canonical string 七要素 + 常量时间比对
    public static String sign(String method, String path, Map<String,String> query,
                              byte[] body, long timestamp, String nonce,
                              String keyId, byte[] secret) throws Exception {
        String sortedQuery = query.entrySet().stream()
                .sorted(Map.Entry.comparingByKey())
                .map(e -> urlEncode(e.getKey()) + "=" + urlEncode(e.getValue()))
                .collect(Collectors.joining("&"));
        String bodyDigest = sha256Hex(body); // 不直接拼 body，太大
        String canonical = String.join("\n",
                method, path, sortedQuery, bodyDigest,
                String.valueOf(timestamp), nonce, keyId);
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(new SecretKeySpec(secret, "HmacSHA256"));
        return hex(mac.doFinal(canonical.getBytes(StandardCharsets.UTF_8)));
    }

    // 3) 服务端校验：时间窗口 + nonce 去重 + 常量时间比对
    public static boolean verify(String method, String path, Map<String,String> query,
                                 byte[] body, long timestamp, String nonce,
                                 String keyId, String expectedSig,
                                 byte[] secret) throws Exception {
        // 时间窗口 ±5 分钟
        if (Math.abs(System.currentTimeMillis() - timestamp) > 300_000) return false;
        // nonce 去重：Redis SETNX nonce:xxx 1 EX 300，此处用伪代码
        // if (!redis.setIfAbsent("nonce:" + nonce, "1", Duration.ofMinutes(5))) return false;
        String actual = sign(method, path, query, body, timestamp, nonce, keyId, secret);
        // 常量时间比对防时序攻击
        return MessageDigest.isEqual(
                actual.getBytes(StandardCharsets.UTF_8),
                expectedSig.getBytes(StandardCharsets.UTF_8));
    }

    private static String sha256Hex(byte[] data) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        return hex(md.digest(data));
    }

    private static String hex(byte[] bytes) {
        StringBuilder sb = new StringBuilder(bytes.length * 2);
        for (byte b : bytes) sb.append(String.format("%02x", b & 0xff));
        return sb.toString();
    }

    private static String urlEncode(String s) {
        // 省略实现，实际用 URLEncoder.encode(s, UTF_8) + 特定字符保留
        return s;
    }
}
